/**
 * The deployed Worker (wrangler.jsonc `main`): the OpenNext handler behind the public-page edge cache
 * (src/lib/edge-cache.ts). Everything else — images, middleware, /api, /admin, client-side navigation —
 * goes to the OpenNext handler unchanged.
 */
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';
import { withEdgeCache, type EdgeCache, type WaitUntil } from './src/lib/edge-cache';

type Handler = { fetch(request: Request, env: unknown, ctx: WaitUntil): Promise<Response> };

export default {
  async fetch(request: Request, env: unknown, ctx: WaitUntil): Promise<Response> {
    const cache = (globalThis as unknown as { caches?: { default?: EdgeCache } }).caches?.default;
    return withEdgeCache(request, ctx, () => (handler as Handler).fetch(request.clone(), env, ctx), cache);
  },
};
